import 'package:flutter/material.dart'; import '../database/db_helper.dart'; import '../services/backup_service.dart'; import '../services/export_service.dart';
class DashboardScreen extends StatefulWidget{const DashboardScreen({super.key});@override State<DashboardScreen> createState()=>_DashboardScreenState();}
class _DashboardScreenState extends State<DashboardScreen>{Map<String,dynamic> s={};@override void initState(){super.initState();_load();}Future<void>_load()async{final x=await DbHelper.instance.resumo();if(mounted)setState(()=>s=x);}Widget card(String t,String v)=>Card(child:ListTile(title:Text(t),trailing:Text(v,style:const TextStyle(fontSize:20,fontWeight:FontWeight.bold))));@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('CANARIL ALMIRANTE')),body:ListView(padding:const EdgeInsets.all(16),children:[card('Aves', '${s['aves']??0}'),card('Ovos registrados','${s['ovos']??0}'),card('Ovos férteis','${s['ferteis']??0}'),card('Fertilidade','${(s['fertilidade']??0).toStringAsFixed(1)}%'),const SizedBox(height:12),FilledButton.icon(onPressed:()=>BackupService().compartilharBackup(),icon:const Icon(Icons.backup),label:const Text('Backup e compartilhar')),FilledButton.icon(onPressed:()=>ExportService().exportarPlantelCsv(),icon:const Icon(Icons.table_view),label:const Text('Exportar plantel CSV')),FilledButton.icon(onPressed:()=>ExportService().relatorio(),icon:const Icon(Icons.assessment),label:const Text('Gerar relatório'))]));}
